export function OverflowDemo({
  overflow = "{{overflow}}",
  height = {{height}},
  longContent = {{longContent}},
  background = "{{background}}",
}) {
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", width: 300 }}
      role="img" aria-label="A fixed-height container whose overflow property decides what happens to content taller than it">
      <div style={{ width: "100%", height, overflow, background, borderRadius: 8, padding: 10, boxSizing: "border-box", border: "1.5px solid #24143033" }}>
        <p style={{ margin: 0, fontWeight: 600 }}>
          Short line one.{longContent && " And a second sentence. And a third sentence, long enough to push past the container's fixed height so overflow has something to do."}
        </p>
      </div>
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430cc" }}>overflow: {overflow} &middot; height {height}px</p>
    </div>
  );
}
